INSERT INTO public.questoes (id, material_id, enunciado, referencia, comentario_professor, ordem, publicado) VALUES
('92221197-568a-4d8d-a8ef-0457e9bfb5b2', '141a9da0-1e22-4a13-ab75-672cbb17e8b8', 'É condição de elegibilidade a idade mínima de _____ anos para o cargo de Presidente da República, _____ anos para o cargo de Governador de Estado e ____ anos para o cargo de Prefeito. Assinale a alternativa que preenche, correta e respectivamente, as lacunas do trecho acima.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2026 / Conselho Regional de Educação Física do Rio Grande do Sul CREF 2 - RS / Advogado / Questão: 39', 'A resposta correta é a "c" (35 – 30 – 21), conforme o art. 14, §3º, VI, alíneas "a" (35 anos para Presidente), "b" (30 anos para Governador) e "c" (21 anos para Prefeito).', 1, true),
('208433c2-9849-4600-bf7d-3c810178b4a1', '141a9da0-1e22-4a13-ab75-672cbb17e8b8', 'José Antônio é brasileiro, tem 29 anos de idade, completados no mês de julho do corrente ano (...) pretende candidatar-se para as próximas eleições, em 2026, oportunidade em que já terá 30 anos completos. Sendo assim, José Antônio poderá candidatar-se nas eleições de 2026 aos seguintes cargos: I. Deputado Estadual ou Deputado Federal.II. Governador ou Vice-Governador do Estado.III. Presidente ou Vice-Presidente da República e Senador da República. Quais estão corretos?', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2025 / Centro de Tecnologia da Informação e Comunicação do Rio Grande do Sul PROCERGS - RS / Analista Técnico - Área: Engenheiro de Segurança do Trabalho / Questão: 20', 'A resposta correta é a "b". Com 30 anos completos, José Antônio atende ao requisito de idade mínima para Deputado (21 anos) e Governador (30 anos), nos termos do art. 14, §3º, VI, "b" e "c". Porém, não atende ao requisito de 35 anos exigido para Presidente/Vice-Presidente e Senador (art. 14, §3º, VI, "a"), o que torna o item III incorreto.', 2, true),
('5bc91dc2-51d2-4967-a74e-683055b3f4f4', '141a9da0-1e22-4a13-ab75-672cbb17e8b8', 'Maria, prefeita municipal, é casada com José, vereador no mesmo município. Considerando o interesse político em ampliar a governabilidade, José decide se candidatar à presidência da Assembleia para o próximo biênio. Considerando o disposto na Constituição Federal sobre a inelegibilidade, assinale a alternativa correta.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Câmara de Piracicaba Camara de Piracicaba - SP / Procurador Legislativo / Questão: 22', 'A resposta correta é a "a". A inelegibilidade reflexa do art. 14, §7º, aplica-se à candidatura para cargos eletivos, e não à eleição interna para a presidência da Casa Legislativa (cargo de organização interna do Legislativo), motivo pelo qual o STF entende não haver óbice à ocupação simultânea desses cargos por cônjuges. As demais alternativas ampliam indevidamente a inelegibilidade constitucional ou atribuem ao Judiciário competência que é do Legislativo.', 3, true),
('936b1f44-de16-42cc-b525-6fc0a39f3147', '141a9da0-1e22-4a13-ab75-672cbb17e8b8', 'De acordo com a Constituição Federal, trata-se de caso de perda ou suspensão de direitos políticos o(a), EXCETO:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Prefeitura de Cidreira - RS / Médico Radiologista / Questão: 19', 'A exceção é a "a", pois o art. 15, III, da CF/1988 exige "condenação criminal transitada em julgado, enquanto durarem seus efeitos" — a condenação sem trânsito em julgado não gera perda ou suspensão de direitos políticos. As demais alternativas correspondem corretamente às hipóteses do art. 15, incisos II, IV e V.', 4, true),
('1ad2f78e-8d09-4ea2-8590-0f4f10de50ee', '141a9da0-1e22-4a13-ab75-672cbb17e8b8', 'A soberania popular será exercida pelo voto direto e secreto, com valor igual para todos, e, nos termos da lei, mediante: I. Referendo.II. Greve.III. Iniciativa Popular. Quais estão corretas?', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Prefeitura de Cruzaltense - RS / Enfermeiro Padrão / Questão: 21', 'A resposta correta é a "d". O art. 14, caput, da CF/1988 prevê que a soberania popular será exercida mediante "plebiscito", "referendo" e "iniciativa popular" (incisos I a III), não incluindo a greve como forma de exercício da soberania popular.', 5, true),
('390044e0-5553-4ebd-99db-c539154b6452', '141a9da0-1e22-4a13-ab75-672cbb17e8b8', 'Afonso, brasileiro de 74 anos e analfabeto, estava assistindo à propaganda eleitoral quando se encantou pela proposta de um candidato. Decidiu então que irá votar nas próximas eleições. Segundo a Constituição Federal, Afonso poderá votar?', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2023 / Prefeitura de Sapucaia do Sul - RS / Motorista / Questão: 15', 'A resposta correta é a "a", pois o art. 14, §1º, II, "a" e "b", da CF/1988 garante o direito de voto, de forma facultativa, tanto para analfabetos quanto para maiores de 70 anos. Afonso pode votar, mesmo não sendo obrigado a fazê-lo.', 6, true),
('082a31c0-12b1-4224-b5a7-79e33547ad77', '141a9da0-1e22-4a13-ab75-672cbb17e8b8', 'No Brasil, o voto e o alistamento eleitoral são obrigatórios para maiores de ___ anos. O voto é facultativo para analfabetos e maiores de ___ anos. Essas regras estão previstas no Artigo 14, §1º e incisos, da Constituição Federal. Assinale a alternativa que preenche, correta e respectivamente, as lacunas do trecho acima.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2022 / Prefeitura de Meridiano - SP / Zelador / Questão: 33', 'A resposta correta é a "c" (18 – 70), conforme o art. 14, §1º, I (obrigatório para maiores de dezoito anos) e §1º, II, "b" (facultativo para maiores de setenta anos).', 7, true);
INSERT INTO public.questao_alternativas (questao_id, letra, texto, correta, ordem) VALUES
('92221197-568a-4d8d-a8ef-0457e9bfb5b2', 'A', '35 – 35 – 21', false, 0),
('92221197-568a-4d8d-a8ef-0457e9bfb5b2', 'B', '35 – 30 – 18', false, 1),
('92221197-568a-4d8d-a8ef-0457e9bfb5b2', 'C', '35 – 30 – 21', true, 2),
('92221197-568a-4d8d-a8ef-0457e9bfb5b2', 'D', '30 – 21 – 18', false, 3),
('92221197-568a-4d8d-a8ef-0457e9bfb5b2', 'E', '30 – 21 – 20', false, 4),
('208433c2-9849-4600-bf7d-3c810178b4a1', 'A', 'Apenas I.', false, 0),
('208433c2-9849-4600-bf7d-3c810178b4a1', 'B', 'Apenas I e II.', true, 1),
('208433c2-9849-4600-bf7d-3c810178b4a1', 'C', 'Apenas I e III.', false, 2),
('208433c2-9849-4600-bf7d-3c810178b4a1', 'D', 'Apenas II e III.', false, 3),
('208433c2-9849-4600-bf7d-3c810178b4a1', 'E', 'I, II e III.', false, 4),
('5bc91dc2-51d2-4967-a74e-683055b3f4f4', 'A', 'A inelegibilidade por parentesco, prevista no art. 14, §7º da CF/1988, não impede que cônjuges, companheiros ou parentes em linha reta, colateral ou por afinidade, até o segundo grau, ocupem, concomitantemente e na mesma unidade da Federação, os cargos de chefe do Poder Executivo e de presidente da Casa Legislativa.', true, 0),
('5bc91dc2-51d2-4967-a74e-683055b3f4f4', 'B', 'A inelegibilidade por parentesco, prevista no art. 14, §7º da CF/1988, por veicular regra de inelegibilidade reflexa, limita o exercício dos direitos políticos fundamentais, inclusive na hipótese descrita no enunciado.', false, 1),
('5bc91dc2-51d2-4967-a74e-683055b3f4f4', 'C', 'A despeito de competir ao Poder Legislativo definir novas hipóteses de inelegibilidade, o Poder Judiciário pode atuar como legislador positivo e editar norma geral e abstrata referente ao processo eleitoral, não havendo que se falar em ofensa ao princípio da separação dos Poderes.', false, 2),
('5bc91dc2-51d2-4967-a74e-683055b3f4f4', 'D', 'A ocupação simultânea das chefias do Poder Executivo e do Poder Legislativo no âmbito municipal por pessoas com alguma relação familiar representa, por si só, prejuízo à fiscalização dos atos do Executivo pelo Legislativo.', false, 3),
('5bc91dc2-51d2-4967-a74e-683055b3f4f4', 'E', 'A ocupação simultânea das chefias do Poder Executivo e do Poder Legislativo no âmbito municipal por pessoas com alguma relação familiar representa, por si só, comprometimento do equilíbrio entre os Poderes.', false, 4),
('936b1f44-de16-42cc-b525-6fc0a39f3147', 'A', 'Condenação criminal, mesmo sem trânsito em julgado.', true, 0),
('936b1f44-de16-42cc-b525-6fc0a39f3147', 'B', 'Cancelamento da naturalização por sentença transitada em julgado.', false, 1),
('936b1f44-de16-42cc-b525-6fc0a39f3147', 'C', 'Improbidade administrativa, nos termos do Art. 37, § 4º.', false, 2),
('936b1f44-de16-42cc-b525-6fc0a39f3147', 'D', 'Recusa de cumprir obrigação a todos imposta ou prestação alternativa, nos termos do art. 5º, VIII.', false, 3),
('936b1f44-de16-42cc-b525-6fc0a39f3147', 'E', 'Incapacidade civil absoluta.', false, 4),
('1ad2f78e-8d09-4ea2-8590-0f4f10de50ee', 'A', 'Apenas I.', false, 0),
('1ad2f78e-8d09-4ea2-8590-0f4f10de50ee', 'B', 'Apenas III.', false, 1),
('1ad2f78e-8d09-4ea2-8590-0f4f10de50ee', 'C', 'Apenas I e II.', false, 2),
('1ad2f78e-8d09-4ea2-8590-0f4f10de50ee', 'D', 'Apenas I e III.', true, 3),
('1ad2f78e-8d09-4ea2-8590-0f4f10de50ee', 'E', 'Apenas II e III.', false, 4),
('390044e0-5553-4ebd-99db-c539154b6452', 'A', 'Sim, pois a Constituição prevê o voto facultativo para os cidadãos brasileiros maiores de 70 anos e/ou analfabetos.', true, 0),
('390044e0-5553-4ebd-99db-c539154b6452', 'B', 'Sim, pois a Constituição Federal prevê o voto obrigatório para todos os cidadãos brasileiros, independentemente de idade ou alfabetização.', false, 1),
('390044e0-5553-4ebd-99db-c539154b6452', 'C', 'Não, pois a Constituição Federal prevê a proibição do voto para os analfabetos.', false, 2),
('390044e0-5553-4ebd-99db-c539154b6452', 'D', 'Não, pois a Constituição Federal prevê a proibição do voto para os maiores de 70 anos.', false, 3),
('390044e0-5553-4ebd-99db-c539154b6452', 'E', 'Sim, pois a Constituição Federal prevê o voto facultativo para os maiores de 21 anos.', false, 4),
('082a31c0-12b1-4224-b5a7-79e33547ad77', 'A', '16 – 50', false, 0),
('082a31c0-12b1-4224-b5a7-79e33547ad77', 'B', '16 – 60', false, 1),
('082a31c0-12b1-4224-b5a7-79e33547ad77', 'C', '18 – 70', true, 2),
('082a31c0-12b1-4224-b5a7-79e33547ad77', 'D', '18 – 60', false, 3),
('082a31c0-12b1-4224-b5a7-79e33547ad77', 'E', '18 – 65', false, 4);